# bringup_A.ps1 - relaunch exactly the canonical AgentsA roster after a crash.
#
# Reads AGENTS_A.json (generated by roster_A.py) and resumes each member through the EXISTING
# guarded launcher launch_one.ps1. launch_one refuses any session that is still alive, locked, or
# disabled (exit 3/4/5), so running this while the fleet is up is safe: every live agent is
# refused, only genuinely-dead members relaunch. It reproduces each agent in its registry mode
# (interactive TUI or gentle -p). This does NOT edit launch_one or the registry - it only calls them.
#
#   powershell -File bringup_A.ps1            # preview the roster (no launches)
#   powershell -File bringup_A.ps1 -DryRun    # show launch_one's per-agent plan, launch nothing
#   powershell -File bringup_A.ps1 -Go        # actually relaunch the dead members
param([switch]$DryRun, [switch]$Go)

$ErrorActionPreference = 'Stop'
$fleet = Join-Path $env:USERPROFILE '.claude\fleet'
$manifest = Join-Path $fleet 'AGENTS_A.json'
$launchOne = Join-Path $fleet 'launch_one.ps1'

if (-not (Test-Path $manifest)) {
    Write-Host 'no AGENTS_A.json yet - run:  python roster_A.py --write'
    exit 1
}
if (-not (Test-Path $launchOne)) {
    Write-Host 'launch_one.ps1 is missing - cannot bring up safely'
    exit 1
}

$data = Get-Content $manifest -Raw -Encoding UTF8 | ConvertFrom-Json
$agents = @($data.agents)
Write-Host ('AgentsA bringup: {0} canonical agents (roster generated {1})' -f $agents.Count, $data.generated)
if (-not $DryRun -and -not $Go) {
    Write-Host 'Preview only. Re-run with -Go to relaunch dead members, or -DryRun for the launch plan.'
}

$launched = 0
$refused = 0
$projects = Join-Path $env:USERPROFILE '.claude\projects'
foreach ($a in $agents) {
    $id = [string]$a.sid
    $name = [string]$a.name
    if (-not $id) { continue }
    $short = if ($id.Length -ge 8) { $id.Substring(0, 8) } else { $id }
    $mode = if ($a.mode -and (@('interactive', 'gentle') -contains [string]$a.mode)) { [string]$a.mode } else { 'gentle' }
    $title = [string]$a.title

    if ($DryRun) {
        Write-Host ('  [dry-run] {0} {1}' -f $name, $short)
        & $launchOne -Id $id -DryRun | Out-Host
        continue
    }
    if (-not $Go) {
        Write-Host ('  {0} {1}  {2}' -f $name, $short, $title)
        continue
    }
    # Independent liveness guard: launch_one treats a session with no sid in any cmdline as alive only
    # if its transcript is under 180s old, but a picker-resumed TUI quiet 3-10 min is still live. Skip
    # anything whose transcript wrote in the last 10 min so bringup cannot duplicate it (audit 2026-07-12).
    $tf = Get-ChildItem (Join-Path $projects "*\$id.jsonl") -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
    if ($tf) {
        $ageS = [int]((Get-Date) - $tf.LastWriteTime).TotalSeconds
        if ($ageS -lt 600) {
            Write-Host ('  SKIP {0} {1} - transcript {2}s old (alive); not relaunching' -f $name, $short, $ageS)
            $refused++
            continue
        }
    }
    if (-not (Test-Path (Join-Path $fleet ('registry\' + $id + '.json')))) {
        Write-Host ('  WARN {0} {1}: registry entry missing - launch_one will use a generic resume prompt' -f $name, $short)
    }
    Write-Host ('  bringup {0} {1} (mode {2})' -f $name, $short, $mode)
    & $launchOne -Id $id -Mode $mode -Title $title | Out-Host
    if ($LASTEXITCODE -eq 0) { $launched++ } else { $refused++ }
}
if ($Go) {
    Write-Host ('done: {0} launched, {1} refused (alive / locked / disabled)' -f $launched, $refused)
}
